sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = {
    initialize: function() {},
    //traz os cursos relacionados com aquela data:
    getCoursesByScheduleDate: function(scheduleDateSysId) {
        var courses = [];

        if (!scheduleDateSysId) {
            return [];
        }

        var gr = new GlideRecord('x_1567520_shark_0_training_schedule');
        if (!gr.get(scheduleDateSysId)) {
            return [];
        }

        var scheduleDate = gr.schedule_date;

        gr = new GlideRecord('x_1567520_shark_0_training_schedule');
        gr.addQuery('schedule_date', scheduleDate);
        gr.query();

        while (gr.next()) {
            if (gr.course) {
                courses.push(gr.course.sys_id.toString());
            }
        }

        return courses;
    },
    //exibe os cursos que o user não está matriculado:
    refQualCourses: function(scheduleDateSysId) {
        var coursesNotToBeShown = [];

        if (!scheduleDateSysId) {
            return [];
        }

        var grDate = new GlideRecord("x_1567520_shark_0_registration");
        grDate.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^registration_status=3');
        grDate.addQuery('schedule_date', scheduleDateSysId);
        grDate.query();

        while (grDate.next()) {
            coursesNotToBeShown.push(grDate.course.sys_id.toString());
        }

        return coursesNotToBeShown;
    },
    //exibe os cursos que o user não concluiu 3 vezes:
    refQualCompletedCourses: function() {
        var userSysId = gs.getUserID();
        var completedCourses = [];

        var grCompleted = new GlideRecord('x_1567520_shark_0_registration');
        grCompleted.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state=3');
        grCompleted.query();

        var courseCount = {};

        while (grCompleted.next()) {
            var courseId = grCompleted.getValue('course');

            if (!courseCount[courseId]) {
                courseCount[courseId] = 0;
            }

            courseCount[courseId]++;

            if (courseCount[courseId] >= 3) {
                completedCourses.push(courseId);
            }
        }

        return completedCourses;
    },
    //impede que o instrutor se matricule nos próprios treinamentos:
    refQualInstructorCourses: function() {
        var userSysId = gs.getUserID();
        var coursesNotToBeShown = [];

        var grSchedule = new GlideRecord('x_1567520_shark_0_training_schedule');
        grSchedule.query();


        while (grSchedule.next()) {
            var instructorSysId = grSchedule.getValue('instructor');

            if (instructorSysId == userSysId) {
                coursesNotToBeShown.push(grSchedule.course.sys_id.toString());
            }
        }

        return coursesNotToBeShown;
    },
    //exibe os cursos com vagas disponiveis:
    refQualCoursesWithNoVacancies: function() {
        var coursesWithNoVacancies = [];

        var grSchedule = new GlideRecord('x_1567520_shark_0_training_schedule');
        grSchedule.query();

        while (grSchedule.next()) {
            var vacancies = grSchedule.number_of_vacancies;

            if (vacancies <= 0) {
                coursesWithNoVacancies.push(grSchedule.course.sys_id.toString());
            }
        }

        return coursesWithNoVacancies;
    },
    //verifica se a matrícula pode ser realizada naquela data
    refQualCoursesWithValidDate: function() {
        var coursesWithValidDate = [];

        var currentDate = new GlideDateTime();
        var grSchedule = new GlideRecord('x_1567520_shark_0_training_schedule');
        grSchedule.query();

        while (grSchedule.next()) {
            var trainingDate = grSchedule.schedule_date;

            var trainingDateAdjusted = new GlideDateTime(trainingDate);
            trainingDateAdjusted.addDaysUTC(-1);

            if (currentDate.before(trainingDateAdjusted)) {
                coursesWithValidDate.push(grSchedule.course.sys_id.toString());
            }
        }

        return coursesWithValidDate;
    },

    getFilteredCourses: function(scheduleDateSysId) {
        var coursesByDate = this.getCoursesByScheduleDate(scheduleDateSysId);
        var coursesToExclude = this.refQualCourses(scheduleDateSysId);
        var completedCourses = this.refQualCompletedCourses();
        var instructorCourses = this.refQualInstructorCourses();
        var coursesWithNoVacancies = this.refQualCoursesWithNoVacancies();
        var coursesWithValidDate = this.refQualCoursesWithValidDate();

        var filteredCourses = coursesByDate.filter(function(course) {
            return coursesToExclude.indexOf(course) === -1 &&
                completedCourses.indexOf(course) === -1 &&
                instructorCourses.indexOf(course) === -1 &&
                coursesWithNoVacancies.indexOf(course) === -1 &&
                coursesWithValidDate.indexOf(course) !== -1;
        });

        return filteredCourses.length > 0 ? "sys_idIN" + filteredCourses.join(",") : "sys_idINnone";
    },   

    type: 'TrainingUtils'
};
